//! Provider 出网时的函数名编解码。

use std::collections::HashMap;

/// Convert a Core tool id to a name accepted by OpenAI Chat Completions.
pub fn to_wire_tool_name(name: &str) -> String {
    name.chars()
        .map(|character| match character {
            '.' | ':' => '_',
            character => character,
        })
        .collect()
}

/// Build a wire-name to Core-id mapping, rejecting ambiguous wire names.
pub fn mappings(names: &[&str]) -> Result<HashMap<String, String>, String> {
    let mut from_wire = HashMap::new();
    for original in names {
        let original = (*original).to_string();
        let wire = to_wire_tool_name(&original);
        if let Some(existing) = from_wire.get(&wire) {
            if existing != &original {
                return Err(format!(
                    "tool name collision: {existing:?} and {original:?} both map to {wire:?}"
                ));
            }
        } else {
            from_wire.insert(wire, original);
        }
    }
    Ok(from_wire)
}

#[cfg(test)]
mod tests {
    use super::{mappings, to_wire_tool_name};

    #[test]
    fn encodes_openai_incompatible_separators() {
        assert_eq!(to_wire_tool_name("fs.list"), "fs_list");
        assert_eq!(to_wire_tool_name("mcp:tool"), "mcp_tool");
    }

    #[test]
    fn leaves_legal_names_unchanged() {
        assert_eq!(to_wire_tool_name("get_time"), "get_time");
    }

    #[test]
    fn mappings_round_trip_to_original_ids() {
        let map = mappings(&["fs.list", "mcp:tool", "get_time"]).unwrap();

        assert_eq!(map.get("fs_list"), Some(&"fs.list".to_string()));
        assert_eq!(map.get("mcp_tool"), Some(&"mcp:tool".to_string()));
        assert_eq!(map.get("get_time"), Some(&"get_time".to_string()));
    }

    #[test]
    fn rejects_collisions_between_different_core_ids() {
        let error = mappings(&["fs.list", "fs_list"]).unwrap_err();
        assert!(error.contains("fs.list"));
        assert!(error.contains("fs_list"));
    }

    #[test]
    fn accepts_duplicate_occurrences_of_same_core_id() {
        let map = mappings(&["get_time", "get_time"]).unwrap();
        assert_eq!(map.len(), 1);
    }
}

